    assertThat(availableTo).containsExactlyInAnyOrder(types);
  }
}

package si.konferenca.registration.acceptance;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import tools.jackson.databind.JsonNode;

/**
 * AC-003-02: the backend started with another options file (ws-new added, ws-ai deactivated)
 * reflects it with no code change.
 */
class ChangedConfigAcceptanceTest extends AcceptanceTestSupport {

  @DynamicPropertySource
  static void settings(DynamicPropertyRegistry registry) {
    registerSettings(
        registry, Map.of("CONFERENCE_CONFIG_PATH", testConfigPath("conference-changed.json")));
  }

  @Test
  @DisplayName("AC-003-02 the form configuration reflects the changed options file")
  void ac_003_02_formConfigReflectsChangedConfiguration() throws Exception {
    JsonNode config = jsonBody(get("/api/form-config"));

    List<String> ids = new ArrayList<>();
    for (JsonNode o : config.path("options")) {
      ids.add(o.path("id").asString());
      if ("ws-new".equals(o.path("id").asString())) {
        assertThat(o.path("name").asString()).isEqualTo("New robotics workshop");
        assertThat(o.path("category").asString()).isEqualTo("WORKSHOP");
      }
    }
    assertThat(ids).contains("ws-new").doesNotContain("ws-ai", "ev-student");
  }

  @Test
  @DisplayName("AC-003-02 registrations follow the changed options file")
  void ac_003_02_registrationFollowsChangedConfiguration() throws Exception {
    Map<String, Object> body = validExternal();
    body.put("options", List.of("ws-new"));
    createdId(postRegistration(body));

    Map<String, Object> deactivated = validExternal();
    deactivated.put("options", List.of("ws-ai"));
    assertThat(errorFields(postRegistration(deactivated))).contains("options");
  }
}

package si.konferenca.registration.acceptance;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.catchThrowable;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.stream.Stream;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import si.konferenca.registration.RegistrationApplication;

/**
 * AC-003-03: the backend refuses to start with an invalid options configuration. Each case starts
 * the application with the acceptance settings; only the options file differs from the control
 * case, which must start.
 */
class InvalidConfigAcceptanceTest {

  static final String CONSENTS =
      "\"consents\": [{\"id\": \"privacy\", \"text\": \"I agree.\", \"mandatory\": true}]";

  @TempDir Path dir;

  static Stream<Arguments> invalidConfigurations() {
    return Stream.of(
        Arguments.of(
            "duplicate identifier",
            "{\"conferenceName\": \"K\", \"options\": ["
                + "{\"id\": \"ws-ai\", \"name\": \"AI workshop\", \"category\": \"WORKSHOP\"},"
                + "{\"id\": \"ws-ai\", \"name\": \"Other AI\", \"category\": \"EVENT\"}], "
                + CONSENTS
                + "}"),
        Arguments.of(
            "unknown category",
            "{\"conferenceName\": \"K\", \"options\": ["
                + "{\"id\": \"ws-ai\", \"name\": \"AI workshop\", \"category\": \"PARTY\"}], "
                + CONSENTS
                + "}"),
        Arguments.of(
            "missing name",
            "{\"conferenceName\": \"K\", \"options\": ["
                + "{\"id\": \"ws-ai\", \"category\": \"WORKSHOP\"}], "
                + CONSENTS
                + "}"));
  }

  @Test
  @DisplayName("AC-003-03 control: the same settings with a valid options file start")
  void ac_003_03_validConfigurationStarts() throws Exception {
    Path valid = write("valid.json", Files.readString(Path.of(validConfigPath())));

    try (ConfigurableApplicationContext context = start(valid)) {
      assertThat(context.isRunning()).isTrue();
    }
  }

  @ParameterizedTest(name = "AC-003-03 an options file with a {0} makes the backend refuse to start")
  @MethodSource("invalidConfigurations")
  void ac_003_03_invalidConfigurationRefusesToStart(String reason, String content)
      throws Exception {
    Path invalid = write("invalid.json", content);

    Throwable failure = catchThrowable(() -> start(invalid).close());

    assertThat(failure).as("start with an options file with a %s", reason).isNotNull();
  }

  private static String validConfigPath() {
    return AcceptanceTestSupport.testConfigPath("conference-test.json");
  }

  private Path write(String name, String content) throws Exception {
    Path file = dir.resolve(name);
    Files.writeString(file, content, StandardCharsets.UTF_8);
    return file;
  }

  private static ConfigurableApplicationContext start(Path config) {
    Map<String, Object> settings =
        AcceptanceTestSupport.settingsMap(
            Map.of("CONFERENCE_CONFIG_PATH", config.toAbsolutePath().toString()));
    settings.put("server.port", "0");
    return new SpringApplicationBuilder(RegistrationApplication.class)
        .properties(settings)
        .run();
  }
}

