  value: string;
  error?: string;
  type?: "text" | "email";
  autoComplete?: string;
  onChange: (value: string) => void;
}

/** A labelled input; its error is shown right after it and linked by aria-describedby. */
export function TextInput({ id, label, value, error, type = "text", autoComplete, onChange }: TextInputProps) {
  const errorId = `${id}-error`;
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <input
        id={id}
        name={id}
        type={type}
        value={value}
        autoComplete={autoComplete}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId : undefined}
        onChange={(event) => onChange(event.target.value)}
      />
      {error && (
        <p id={errorId} role="alert" className="error">
          {error}
        </p>
      )}
    </div>
  );
}

import type { FormOption, OptionCategory } from "../types";

export const GROUP_TITLES: [OptionCategory, string][] = [
  ["WORKSHOP", "Workshops"],
  ["EVENT", "Events"],
  ["MEAL", "Meals"],
  ["OTHER", "Other activities"],
];

interface OptionGroupsProps {
  options: FormOption[];
  selected: ReadonlySet<string>;
  error?: string;
  onToggle: (id: string) => void;
}

/** The options of the chosen type as checkboxes, grouped by category (BR-04); none preselected. */
export function OptionGroups({ options, selected, error, onToggle }: OptionGroupsProps) {
  return (
    <div className="options">
      {GROUP_TITLES.map(([category, title]) => {
        const inGroup = options.filter((option) => option.category === category);
        if (inGroup.length === 0) {
          return null;
        }
        return (
          <fieldset key={category}>
            <legend>{title}</legend>
            {inGroup.map((option) => (
              <div className="choice" key={option.id}>
                <input
                  type="checkbox"
                  id={`option-${option.id}`}
                  checked={selected.has(option.id)}
                  onChange={() => onToggle(option.id)}
                />
                <label htmlFor={`option-${option.id}`}>{option.name}</label>
              </div>
            ))}
          </fieldset>
        );
      })}
      {error && (
        <p id="options-error" role="alert" className="error">
          {error}
        </p>
      )}
    </div>
  );
}

