  cleanup();
  delete window.grecaptcha;
  document.head.querySelectorAll("script").forEach((s) => s.remove());
});

function fakeGrecaptcha() {
  const handlers: { callback?: (t: string) => void; expired?: () => void; sitekey?: string } = {};
  const api = {
    ready: vi.fn((callback: () => void) => callback()),
    render: vi.fn(
      (
        _container: HTMLElement,
        p: { sitekey: string; callback: (t: string) => void; "expired-callback": () => void },
      ) => {
        handlers.sitekey = p.sitekey;
        handlers.callback = p.callback;
        handlers.expired = p["expired-callback"];
        return 7;
      },
    ),
    reset: vi.fn(),
  };
  return { api, handlers };
}

describe("Captcha in test mode", () => {
  it("yields the test token when ticked and nothing when unticked", () => {
    const onToken = vi.fn();
    const { rerender } = render(
      <Captcha siteKey="" testMode checked={false} resetSignal={0} onToken={onToken} />,
    );

    fireEvent.click(screen.getByRole("checkbox", { name: "I am not a robot (test mode)" }));
    expect(onToken).toHaveBeenLastCalledWith(TEST_TOKEN);

    rerender(<Captcha siteKey="" testMode checked resetSignal={0} onToken={onToken} />);
    fireEvent.click(screen.getByRole("checkbox"));
    expect(onToken).toHaveBeenLastCalledWith(null);
  });

  it("shows its error linked to the checkbox", () => {
    render(
      <Captcha siteKey="" testMode checked={false} error="Confirm" resetSignal={0} onToken={vi.fn()} />,
    );
    expect(screen.getByRole("checkbox")).toHaveAccessibleDescription("Confirm");
    expect(screen.getByRole("alert")).toHaveTextContent("Confirm");
  });
});

describe("Captcha with Google reCAPTCHA", () => {
  it("renders the widget with the site key and passes tokens on", () => {
    const { api, handlers } = fakeGrecaptcha();
    window.grecaptcha = api;
    const onToken = vi.fn();

    render(<Captcha siteKey="site" testMode={false} checked={false} resetSignal={0} onToken={onToken} />);

    expect(api.render).toHaveBeenCalledTimes(1);
    expect(handlers.sitekey).toBe("site");
    handlers.callback?.("google-token");
    expect(onToken).toHaveBeenLastCalledWith("google-token");
    handlers.expired?.();
    expect(onToken).toHaveBeenLastCalledWith(null);
    expect(screen.queryByRole("checkbox")).toBeNull();
  });

  it("resets the widget when the reset signal changes", () => {
    const { api } = fakeGrecaptcha();
    window.grecaptcha = api;
    const { rerender } = render(
      <Captcha siteKey="site" testMode={false} checked={false} resetSignal={0} onToken={vi.fn()} />,
    );
    expect(api.reset).not.toHaveBeenCalled();

    rerender(
      <Captcha siteKey="site" testMode={false} checked={false} resetSignal={1} onToken={vi.fn()} />,
    );
    expect(api.reset).toHaveBeenCalledWith(7);
  });

  it("does not reset a widget that was never rendered", () => {
    const { rerender } = render(
      <Captcha siteKey="site" testMode={false} checked={false} resetSignal={0} onToken={vi.fn()} />,
    );
    const { api } = fakeGrecaptcha();
    window.grecaptcha = api;
    rerender(
      <Captcha siteKey="site" testMode={false} checked={false} resetSignal={2} onToken={vi.fn()} />,
    );
    expect(api.reset).not.toHaveBeenCalled();
  });

  it("loads the script once and renders after it loaded", () => {
    const { unmount } = render(
      <Captcha siteKey="site" testMode={false} checked={false} resetSignal={0} onToken={vi.fn()} />,
    );
    const scripts = document.head.querySelectorAll(`script[src="${RECAPTCHA_SCRIPT}"]`);
    expect(scripts).toHaveLength(1);
    expect((scripts[0] as HTMLScriptElement).async).toBe(true);

    const { api } = fakeGrecaptcha();
    window.grecaptcha = api;
    act(() => {
      scripts[0].dispatchEvent(new Event("load"));
    });
    expect(api.render).toHaveBeenCalledTimes(1);
    act(() => {
      scripts[0].dispatchEvent(new Event("load"));
    });
    expect(api.render).toHaveBeenCalledTimes(1);
    unmount();

    render(<Captcha siteKey="site" testMode={false} checked={false} resetSignal={0} onToken={vi.fn()} />);
    expect(document.head.querySelectorAll(`script[src="${RECAPTCHA_SCRIPT}"]`)).toHaveLength(1);
  });

  it("ignores a load event without the reCAPTCHA API and after unmount", () => {
    const { unmount } = render(
      <Captcha siteKey="site" testMode={false} checked={false} resetSignal={0} onToken={vi.fn()} />,
    );
    const script = document.head.querySelector(`script[src="${RECAPTCHA_SCRIPT}"]`) as HTMLScriptElement;
    act(() => {
      script.dispatchEvent(new Event("load"));
    });
    unmount();
    const { api } = fakeGrecaptcha();
    window.grecaptcha = api;
    script.dispatchEvent(new Event("load"));
    expect(api.render).not.toHaveBeenCalled();
  });

  it("shows the error below the widget", () => {
    window.grecaptcha = fakeGrecaptcha().api;
    render(
      <Captcha siteKey="site" testMode={false} checked={false} error="Confirm" resetSignal={0} onToken={vi.fn()} />,
    );
    expect(screen.getByRole("alert")).toHaveTextContent("Confirm");
  });
});

import "@testing-library/jest-dom/vitest";
import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import App, { LOAD_ERROR } from "../App";
import type { FormConfig } from "../types";
import { Confirmation } from "./Confirmation";
import { OptionGroups } from "./OptionGroups";
import { GENERAL_ERROR, RegistrationForm } from "./RegistrationForm";
import { TextInput } from "./TextInput";

const config: FormConfig = {
  captchaSiteKey: "",
  captchaTestMode: true,
  options: [
    { id: "ws-both", name: "Both workshop", category: "WORKSHOP", availableTo: ["EXTERNAL", "STUDENT"] },
    { id: "ws-ext", name: "External workshop", category: "WORKSHOP", availableTo: ["EXTERNAL"] },
    { id: "ml", name: "Lunch", category: "MEAL", availableTo: ["STUDENT"] },
  ],
  consents: [{ id: "privacy", text: "I agree", mandatory: true }],
};

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
});

function backend(status: number, body: unknown) {
  const posts: unknown[] = [];
  vi.stubGlobal(
    "fetch",
    vi.fn(async (url: string, init?: RequestInit) => {
      if (url === "/api/form-config") {
        return new Response(JSON.stringify({ ...config, conferenceName: "Konferenca" }), { status: 200 });
      }
      posts.push(JSON.parse(String(init?.body)));
      return new Response(JSON.stringify(body), { status });
    }),
  );
  return posts;
}

function fill(label: RegExp, value: string) {
  fireEvent.change(screen.getByLabelText(label), { target: { value } });
}

function fillStudent() {
  fireEvent.click(screen.getByRole("radio", { name: "Student" }));
  fill(/^First name/, " Luka ");
  fill(/^Last name/, "Horvat");
  fill(/^Email/, "l@x.org");
  fill(/^Study institution/, "Uni");
  fill(/^Study programme/, "CS");
  fill(/^Student ID/, "1");
  fireEvent.click(screen.getByRole("checkbox", { name: "I agree" }));
  fireEvent.click(screen.getByRole("checkbox", { name: /test mode/ }));
}

describe("RegistrationForm", () => {
  it("shows no fields before a type is chosen", () => {
    render(<RegistrationForm config={config} onRegistered={vi.fn()} />);
    expect(screen.queryAllByRole("textbox")).toHaveLength(0);
    expect(screen.queryByRole("button", { name: "Register" })).toBeNull();
  });

  it("drops options the new type cannot select and clears errors", () => {
    render(<RegistrationForm config={config} onRegistered={vi.fn()} />);
    fireEvent.click(screen.getByRole("radio", { name: "External participant" }));
    fireEvent.click(screen.getByRole("checkbox", { name: "Both workshop" }));
    fireEvent.click(screen.getByRole("checkbox", { name: "External workshop" }));
    fireEvent.click(screen.getByRole("button", { name: "Register" }));
    expect(screen.getAllByRole("alert").length).toBeGreaterThan(0);

    fireEvent.click(screen.getByRole("radio", { name: "Student" }));

    expect(screen.queryAllByRole("alert")).toHaveLength(0);
    expect(screen.getByRole("checkbox", { name: "Both workshop" })).toBeChecked();
    fireEvent.click(screen.getByRole("radio", { name: "External participant" }));
    expect(screen.getByRole("checkbox", { name: "External workshop" })).not.toBeChecked();
    expect(screen.getByRole("checkbox", { name: "Both workshop" })).toBeChecked();
  });

  it("sends a student request with trimmed names in the confirmation", async () => {
    const posts = backend(201, { id: "x" });
    const onRegistered = vi.fn();
    render(<RegistrationForm config={config} onRegistered={onRegistered} />);
    fillStudent();
    fireEvent.click(screen.getByRole("checkbox", { name: "Lunch" }));

    fireEvent.click(screen.getByRole("button", { name: "Register" }));

    await waitFor(() => expect(onRegistered).toHaveBeenCalled());
    expect(posts).toEqual([
      {
        type: "STUDENT",
        firstName: " Luka ",
        lastName: "Horvat",
        email: "l@x.org",
        organization: null,
        studyInstitution: "Uni",
        studyProgramme: "CS",
        studentId: "1",
        options: ["ml"],
        consents: ["privacy"],
        captchaToken: "test-pass",
      },
    ]);
    expect(onRegistered).toHaveBeenCalledWith({
      firstName: "Luka",
      lastName: "Horvat",
      optionNames: ["Lunch"],
    });
  });

  it("shows field errors it cannot place as a general message", async () => {
    backend(400, {
      errors: [
        { field: "type", message: "Choose a type." },
        { field: "body", message: "Bad body." },
        { field: "consents", message: "Consent needed." },
        { field: "captchaToken", message: "Robot?" },
      ],
    });
    render(<RegistrationForm config={config} onRegistered={vi.fn()} />);
    fillStudent();

    fireEvent.click(screen.getByRole("button", { name: "Register" }));

    expect(await screen.findByText("Choose a type. Bad body.")).toBeVisible();
    expect(screen.getByText("Consent needed.")).toBeVisible();
    expect(screen.getByRole("checkbox", { name: /test mode/ })).toHaveAccessibleDescription("Robot?");
    expect(screen.getByRole("checkbox", { name: /test mode/ })).toBeChecked();
  });

  it("resets a Google captcha after a failed submission", async () => {
    backend(500, {});
    const reset = vi.fn();
    window.grecaptcha = {
      ready: (callback) => callback(),
      render: (_c, p) => {
        p.callback("google-token");
        return 3;
      },
      reset,
    };
    render(
      <RegistrationForm config={{ ...config, captchaTestMode: false, captchaSiteKey: "site" }} onRegistered={vi.fn()} />,
    );
    fireEvent.click(screen.getByRole("radio", { name: "Student" }));
    fill(/^First name/, "L");
    fill(/^Last name/, "H");
    fill(/^Email/, "l@x.org");
    fill(/^Study institution/, "U");
    fill(/^Study programme/, "P");
    fill(/^Student ID/, "1");
    fireEvent.click(screen.getByRole("checkbox", { name: "I agree" }));

    fireEvent.click(screen.getByRole("button", { name: "Register" }));

    expect(await screen.findByText(GENERAL_ERROR)).toBeVisible();
    expect(reset).toHaveBeenCalledWith(3);
    fireEvent.click(screen.getByRole("button", { name: "Register" }));
    expect(await screen.findByText("Please confirm that you are not a robot.")).toBeVisible();
    delete window.grecaptcha;
  });

  it("ignores a second submit while the first is running", async () => {
    let release: (r: Response) => void = () => undefined;
    const fetchMock = vi.fn(
      () =>
        new Promise<Response>((resolve) => {
          release = resolve;
        }),
    );
    vi.stubGlobal("fetch", fetchMock);
    render(<RegistrationForm config={config} onRegistered={vi.fn()} />);
    fillStudent();

    fireEvent.click(screen.getByRole("button", { name: "Register" }));
    expect(screen.getByRole("button", { name: "Register" })).toBeDisabled();
    fireEvent.submit(screen.getByRole("button", { name: "Register" }).closest("form") as HTMLFormElement);
    release(new Response(JSON.stringify({ id: "x" }), { status: 201 }));

    await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));
  });
});

describe("App", () => {
  it("names the conference and shows the confirmation after registering", async () => {
    backend(201, { id: "x" });
    render(<App />);
    expect(screen.getByText("Loading…")).toBeVisible();
    expect(await screen.findByRole("heading", { name: "Konferenca: registration" })).toBeVisible();
    fillStudent();
    fireEvent.click(screen.getByRole("button", { name: "Register" }));
    expect(await screen.findByRole("heading", { name: "Registration received" })).toBeVisible();
    expect(screen.queryByText("Loading…")).toBeNull();
  });

  it("explains when the form cannot be loaded", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => new Response("", { status: 503 })));
    render(<App />);
    expect(await screen.findByRole("alert")).toHaveTextContent(LOAD_ERROR);
    expect(screen.getByRole("heading", { name: "Conference registration" })).toBeVisible();
    expect(screen.queryByText("Loading…")).toBeNull();
  });

  it("does not update after unmounting", async () => {
    let release: (r: Response) => void = () => undefined;
    vi.stubGlobal("fetch", vi.fn(() => new Promise<Response>((resolve) => (release = resolve))));
    const { unmount } = render(<App />);
    unmount();
    release(new Response("", { status: 500 }));
    await new Promise((r) => setTimeout(r, 0));
    expect(document.body.textContent).toBe("");
  });
});

describe("small components", () => {
  it("TextInput links its error and marks the input invalid", () => {
    const onChange = vi.fn();
    const { rerender } = render(<TextInput id="email" label="Email" value="" onChange={onChange} />);
    const input = screen.getByLabelText("Email");
    expect(input).toHaveAttribute("type", "text");
    expect(input).not.toHaveAttribute("aria-invalid");
    fireEvent.change(input, { target: { value: "a" } });
    expect(onChange).toHaveBeenCalledWith("a");

    rerender(<TextInput id="email" label="Email" type="email" value="a" error="Bad" onChange={onChange} />);
    expect(input).toHaveAttribute("type", "email");
    expect(input).toHaveAttribute("aria-invalid", "true");
    expect(input).toHaveAccessibleDescription("Bad");
  });

  it("OptionGroups hides empty groups and reports toggles", () => {
    const onToggle = vi.fn();
    render(
      <OptionGroups options={config.options.slice(0, 1)} selected={new Set()} error="Nope" onToggle={onToggle} />,
    );
    expect(screen.getAllByRole("group")).toHaveLength(1);
    expect(screen.getByRole("group", { name: "Workshops" })).toBeVisible();
    fireEvent.click(screen.getByRole("checkbox", { name: "Both workshop" }));
    expect(onToggle).toHaveBeenCalledWith("ws-both");
    expect(screen.getByRole("alert")).toHaveTextContent("Nope");
  });

  it("Confirmation lists options or says there are none", () => {
    const { rerender } = render(<Confirmation firstName="A" lastName="B" optionNames={["Lunch"]} />);
    expect(screen.getByRole("listitem")).toHaveTextContent("Lunch");
    expect(screen.getByText(/Thank you, A B\./)).toBeVisible();
    rerender(<Confirmation firstName="A" lastName="B" optionNames={[]} />);
    expect(screen.queryByRole("list")).toBeNull();
    expect(screen.getByText("No optional activities selected.")).toBeVisible();
  });
});

